-- ============================================================================
-- EM-HS: Datenbank-Update für neue Startseite, Wochenplan und Benutzerverwaltung
-- Ziel: Datenbank db_emhs auf dem Server (Stand db_emhs (2).sql vom 16.10.2026)
--
-- Das Skript löscht nichts und kann gefahrlos auch ein zweites Mal ausgeführt werden.
--  * legt die neuen Tabellen an (nur falls noch nicht vorhanden)
--  * ergänzt fehlende Spalten in wochenplan_eintraege, wochenplan_kwinfo, wochenplan_quicktexte
--  * übernimmt den Wochenplan aus wochenplan.json (940 Einträge, 82 KW-Infos),
--    die Quick-Texte, die Meldungen fürs Schwarze Brett und die Telefonnummer 6749
--  * die alten Testeinträge aus KW 31-33/2026 werden durch die echten Einträge ersetzt;
--    die Testtexte bleiben in wochenplan_verlauf erhalten
-- In phpMyAdmin: Datenbank db_emhs auswählen -> Reiter "Importieren" -> diese Datei.
-- ============================================================================
SET NAMES utf8mb4;

-- ---------- neue Spalten in bestehenden Tabellen ----------
ALTER TABLE `wochenplan_eintraege` ADD COLUMN IF NOT EXISTS `version` int(11) NOT NULL DEFAULT 0;
ALTER TABLE `wochenplan_eintraege` ADD COLUMN IF NOT EXISTS `geaendert_von` varchar(255) DEFAULT NULL;
ALTER TABLE `wochenplan_kwinfo` ADD COLUMN IF NOT EXISTS `version` int(11) NOT NULL DEFAULT 0;
ALTER TABLE `wochenplan_kwinfo` ADD COLUMN IF NOT EXISTS `geaendert_von` varchar(255) DEFAULT NULL;
ALTER TABLE `wochenplan_quicktexte` ADD COLUMN IF NOT EXISTS `html` text DEFAULT NULL;
ALTER TABLE `wochenplan_quicktexte` ADD COLUMN IF NOT EXISTS `nutzung` int(11) NOT NULL DEFAULT 0;

-- ---------- neue Tabellen ----------
CREATE TABLE IF NOT EXISTS `wochenplan_sperren` (
  `jahr` int(11) NOT NULL,
  `kw` int(11) NOT NULL,
  `feld` varchar(12) NOT NULL,
  `user_id` int(11) NOT NULL,
  `user_name` varchar(255) NOT NULL,
  `aktiv_am` datetime NOT NULL,
  PRIMARY KEY (`jahr`,`kw`,`feld`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `wochenplan_verlauf` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `jahr` int(11) NOT NULL,
  `kw` int(11) NOT NULL,
  `feld` varchar(12) NOT NULL,
  `inhalt` text DEFAULT NULL,
  `user_name` varchar(255) NOT NULL,
  `zeitpunkt` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_feld` (`jahr`,`kw`,`feld`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `startseite_meldungen` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `titel` varchar(150) NOT NULL,
  `inhalt` text NOT NULL,
  `kategorie` varchar(30) NOT NULL DEFAULT 'info',
  `autor_name` varchar(100) NOT NULL,
  `autor_id` int(11) DEFAULT NULL,
  `angepinnt` tinyint(1) NOT NULL DEFAULT 0,
  `archiviert` tinyint(1) NOT NULL DEFAULT 0,
  `gueltig_bis` date DEFAULT NULL,
  `erstellt_am` datetime NOT NULL DEFAULT current_timestamp(),
  `geaendert_am` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_liste` (`archiviert`,`angepinnt`,`erstellt_am`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `startseite_kommentare` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `meldung_id` int(11) NOT NULL,
  `autor_name` varchar(100) NOT NULL,
  `autor_id` int(11) DEFAULT NULL,
  `inhalt` text NOT NULL,
  `erstellt_am` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_meldung` (`meldung_id`,`erstellt_am`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `startseite_kennzahlen` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `titel` varchar(80) NOT NULL,
  `wert` varchar(30) NOT NULL,
  `hinweis` varchar(80) NOT NULL DEFAULT '',
  `fortschritt` int(11) DEFAULT NULL,
  `sortierung` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `startseite_einstellungen` (
  `schluessel` varchar(50) NOT NULL,
  `wert` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`schluessel`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `startseite_gelesen` (
  `user_id` int(11) NOT NULL,
  `schluessel` varchar(80) NOT NULL,
  `gelesen_am` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`user_id`,`schluessel`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `benutzer_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `admin_id` int(11) DEFAULT NULL,
  `admin_name` varchar(255) NOT NULL,
  `aktion` varchar(20) NOT NULL,
  `benutzer_id` int(11) DEFAULT NULL,
  `benutzer_name` varchar(255) NOT NULL,
  `details` varchar(1000) NOT NULL DEFAULT '',
  `zeitpunkt` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_zeit` (`zeitpunkt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `mitarbeiter_ausweise` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `mitarbeiter_id` int(11) NOT NULL,
  `rfid` varchar(191) NOT NULL,
  `bezeichnung` varchar(60) NOT NULL DEFAULT '',
  `hauptausweis` tinyint(1) NOT NULL DEFAULT 0,
  `erstellt_am` datetime NOT NULL DEFAULT current_timestamp(),
  `erstellt_von` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rfid` (`rfid`),
  KEY `idx_mitarbeiter` (`mitarbeiter_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ---------- Daten ----------



-- Ende
